{
  "pains": [
    {
      "id": "pain:down-mid-service",
      "statement": "The terminals drop mid-service and we can't run cards, and cards are almost all of our sales.",
      "element": "b2b:ease_of_doing_business:availability",
      "shape": {
        "surface": "Terminals disconnect, freeze or reboot during service, card readers stop talking to the POS, and kitchen tickets stop printing.",
        "operational": "Staff restart the terminal, move to another station, re-fire tickets by hand, and turn away guests who have no cash; the owner calls support from the floor while the dining room fills up.",
        "personal": null,
        "personal_note": "No source read shows what an outage costs the owner or the server personally. The reviews stop at lost sales and failed equipment (src:8 counts seven months of lost sales, src:1 counts the share of sales that are card). Reviewers on Capterra are writing about a product, not about their evening, so this rung needs a customer call: see q:pains-personal-rung."
      },
      "workflow": "Dinner service on the iPad terminals and card readers on the floor, at the moment between taking the order and running the card: the terminal loses its connection, the payment device stops reading back to the POS, and the network printer in the kitchen goes quiet.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Bad weather or any internet interruption, because the system is cloud-based and there is no counter to fall back to.",
          "cites": ["src:42"]
        },
        {
          "event": "A software or iPad update pushed during service, which takes terminals out mid-shift.",
          "cites": ["src:3"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "disconnect every single day leaving us with a terminal down",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "unable to take credit cards which is 80% of our sales",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "outages nearly every day or every other day",
              "cites": ["src:8"]
            },
            {
              "situation": "venting",
              "verbatim": "we never know if the system is going to work or not.",
              "cites": ["src:41"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "The system went down often, and it was VERY difficult to get a hold of tech support.",
              "cites": ["src:36"]
            },
            {
              "situation": "venting",
              "verbatim": "We are still having problems with the system, accurate reporting, credit card processing",
              "cites": ["src:30"]
            }
          ],
          "costs_them": "Sales that cannot be rung at all: src:1 puts card at 80% of the restaurant's revenue and src:8 counts lost sales across a seven-month period.",
          "fears": "That the outage lands on the busiest night and guests who were turned away do not come back; src:41 frames it as never knowing whether the system will work at all.",
          "dream_outcome": "Service keeps running and cards keep clearing whether or not the internet is up, with no decision to make on the floor."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "It froze and had to restart the point of sale all the time",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "I've had $300 bar tabs completely disappear",
              "cites": ["src:28"]
            },
            {
              "situation": "venting",
              "verbatim": "It's internet based and in the south we often have inclement weather.",
              "cites": ["src:42"]
            },
            {
              "situation": "venting",
              "verbatim": "which caused issues with kitchen printing and network printing in general",
              "cites": ["src:39"]
            }
          ],
          "costs_them": "Restarts and lost tabs in the middle of a section, and tickets that have to be walked or re-fired to the kitchen when the printer drops.",
          "fears": "Carrying the guest's anger for something they cannot fix, and eating a disappeared tab; src:28 describes three-hundred-dollar tabs vanishing.",
          "dream_outcome": "The terminal takes the order and the kitchen gets it, every time, with no restart in the middle of a shift."
        }
      },
      "segments": ["seg:independent", "seg:multi"],
      "feature_ref": "feat:offline",
      "feature_note": "feat:offline is the direct answer. The bar is set by src:1, a buyer of a competitor that also sells offline mode: 'Offline mode is an absolute joke'. Buyers in this market have been sold offline mode before and do not believe the claim, so the proof matters more than the feature name.",
      "cites": ["src:1", "src:36", "src:41"]
    },
    {
      "id": "pain:nobody-answers-while-were-open",
      "statement": "When it breaks mid-service you can't get a human, and 48 hours is not an answer when it's your point of sale.",
      "element": "b2b:ease_of_doing_business:responsiveness",
      "shape": {
        "surface": "Calls sit on hold, cases get escalated, callbacks do not come, and the person who finally answers cannot make a decision.",
        "operational": "The owner or GM fixes it themselves, calls back week after week, or works around the broken thing indefinitely; larger operators put a staff member on the phone with the vendor most of the day.",
        "personal": "Roughly three hours a week of the owner's own time goes to chasing the vendor instead of running the restaurant (src:6)."
      },
      "workflow": "On the phone to the POS vendor's support line from the pass or the back office during service, with the terminal, printer or card reader down and the room full; then again through the support portal, where the case is escalated and nobody calls back.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A billing or equipment dispute that needs a human to resolve, which drags on for months while the money is out.",
          "cites": ["src:40"]
        },
        {
          "event": "A hardware failure during service, when the answer comes with a 48-hour SLA that does not fit a restaurant's day.",
          "cites": ["src:27"]
        }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "how can you wait 48 hours to solve a problem with your point of sale?",
              "cites": ["src:27"]
            },
            {
              "situation": "venting",
              "verbatim": "You'll end up fixing everything yourself.",
              "cites": ["src:43"]
            },
            {
              "situation": "venting",
              "verbatim": "It's impossible to solve a problem. Zero human contact.",
              "cites": ["src:44"]
            },
            {
              "situation": "venting",
              "verbatim": "You make it so difficult to talk to anyone about any issue",
              "cites": ["src:13"]
            },
            {
              "situation": "venting",
              "verbatim": "They may have a lot of useful software, but if you ever need help it's almost impossible to get it.",
              "cites": ["src:48"]
            },
            {
              "situation": "venting",
              "verbatim": "three hours a week dealing with issues",
              "cites": ["src:6"]
            }
          ],
          "costs_them": "Three hours a week of the owner's own time (src:6), plus money that sits unresolved: src:48 is owed over $1,700 nine months in, src:40 waited two months for a refund.",
          "fears": "That the thing the whole restaurant runs on has nobody behind it, and the next failure is theirs alone to solve; src:44 puts it as zero human contact.",
          "dream_outcome": "One person who answers during service, knows the account, and can decide something without an escalation."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Over and over I've called for 10 months now",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "our tech guy spends 70 percent of his day on the phone with support",
              "cites": ["src:11"]
            },
            {
              "situation": "venting",
              "verbatim": "customer support non-existant",
              "cites": ["src:15"]
            }
          ],
          "costs_them": "The operations or tech person's day disappears into the vendor's queue; src:11 puts it at 70 percent of one person's day.",
          "fears": "Being the one who recommended the system and having no answer for the owner when it breaks again.",
          "dream_outcome": "Issues that get closed the day they are raised, without them having to chase."
        }
      },
      "segments": ["seg:independent", "seg:multi"],
      "feature_ref": null,
      "feature_note": "Nothing in the company artifact's feature list kills this; support is a service, not a feature, and brain/company lists none. Toast's own buyers raise the identical complaint (src:43, src:44, src:48), so this is the pain the category has not solved rather than one Toast can claim today. It belongs to the offer and the objection list, not to a feature page.",
      "cites": ["src:27", "src:43", "src:13"]
    },
    {
      "id": "pain:commission-eats-the-order",
      "statement": "Every delivery order goes out at a 25 to 30 percent cut, so the busiest nights are the ones we make the least on.",
      "element": "b2b:functional:cost_reduction",
      "shape": {
        "surface": "A quarter to a third of every delivery ticket goes to DoorDash, Grubhub or UberEats before any food cost.",
        "operational": "Operators raise prices on the apps, push regulars to order direct, and stand up their own ordering site to move volume off the marketplaces.",
        "personal": null,
        "personal_note": "The reviews read are written in business terms: dollars paid, percentages reclaimed, revenue shifted. None shows what the commission costs the owner personally. See q:pains-personal-rung."
      },
      "workflow": "Month-end reconciliation of the delivery apps' payout statements against gross sales in the accounting file, where the commission, merchant and processing lines land before food cost and labor: src:24 totals over $39,000 a year across those lines.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Fee caps being lifted or renegotiated: NYC's permanent 15% delivery cap plus 5% on other fees is the only thing holding commissions down where it applies.",
          "cites": ["src:35", "src:45"]
        },
        {
          "event": "A first look at a full year of app payout statements, which is where the annual commission total becomes visible.",
          "cites": ["src:24"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "our business paid over $39,000 in commission, merchant, and processing fees to the third-party delivery apps",
              "cites": ["src:24"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "I do not have to pay 25-30% fee to 3rd party delivery",
              "cites": ["src:25"]
            },
            {
              "situation": "venting",
              "verbatim": "Why do they continue giving away a big percentage of their profits to these other",
              "cites": ["src:31"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "Lower cost on commission comparing to other platforms such as ubereats, grubhub",
              "cites": ["src:32"]
            },
            {
              "situation": "when_looking",
              "verbatim": "keeps more of every sale in our business instead of paying large commission fees",
              "cites": ["src:26"]
            }
          ],
          "costs_them": "Tens of thousands a year off the top line: src:24 counts over $39,000 in commission, merchant and processing fees against a median full-service pre-tax margin of 2.8% (src:46).",
          "fears": "That the marketplace owns the customer and the restaurant becomes a kitchen working for someone else's app.",
          "dream_outcome": "Delivery and pickup volume running through their own site at a flat fee, with the guest's name and order history theirs."
        }
      },
      "segments": ["seg:independent", "seg:multi"],
      "feature_ref": "feat:online",
      "feature_note": "feat:online is exactly this: a commission-free ordering channel. The buyer quotes here come from customers of two competing commission-free products (Owner.com, ChowNow), which means the pain is real and already being sold against, so the angle has to be the switch, not the discovery.",
      "cites": ["src:24", "src:31"]
    },
    {
      "id": "pain:orders-from-everywhere",
      "statement": "Every delivery channel has its own device and its own menu, so orders go missing and the price on one app is wrong for weeks before anyone notices.",
      "element": "b2b:ease_of_doing_business:integration",
      "shape": {
        "surface": "Orders arrive per channel on separate tablets, some never reach the kitchen at all, and menus and prices drift apart between the POS and each marketplace.",
        "operational": "Someone re-keys marketplace orders into the POS by hand, and a manager edits the same item separately in every channel's back office; when it breaks, nobody can tell which layer broke it.",
        "personal": null,
        "personal_note": "No source read shows the personal cost. The Deliverect and ChowNow reviewers describe lost orders and broken integrations in operational terms only. See q:pains-personal-rung."
      },
      "workflow": "The expo station during dinner, where the delivery tablets sit next to the POS: an order lands on the Glovo, Otter or Cuboh tablet, has to be keyed into the POS by hand, and a price changed in the POS never makes it back out to the marketplace menus.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Adding or switching a delivery channel, where onboarding drags and orders are lost while it is half-connected.",
          "cites": ["src:17"]
        }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "cost you money in lost orders",
              "cites": ["src:17"]
            },
            {
              "situation": "venting",
              "verbatim": "perdevamo ordini sopratutto con Glovo",
              "cites": ["src:18"]
            },
            {
              "situation": "venting",
              "verbatim": "With new Cuboh integration, it's not restaurant friendly",
              "cites": ["src:34"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "The integrators they work with have been poor or non-responsive.",
              "cites": ["src:38"]
            }
          ],
          "costs_them": "Orders that were paid for and never made, plus months of half-working setup: src:17 is six months in and still not working seamlessly.",
          "fears": "That the refunds and the bad reviews land on the restaurant for a failure that happened in somebody else's integration.",
          "dream_outcome": "Every channel's orders land in one place on their own, and one menu edit reaches all of them."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "POS integration with OTTER. When something goes wrong, it's difficult to find and fix",
              "cites": ["src:33"]
            },
            {
              "situation": "venting",
              "verbatim": "missing products and corrupted information on the website",
              "cites": ["src:19"]
            }
          ],
          "costs_them": "Time lost tracing a failure across three vendors before anyone will own it.",
          "fears": "No source shows the fear; the two quotes stop at the difficulty of finding and fixing the break.",
          "dream_outcome": "One place to look when a channel order goes wrong, and one vendor who owns the answer."
        }
      },
      "segments": ["seg:independent"],
      "feature_ref": "feat:kds",
      "feature_note": "feat:kds claims exactly this ('every order from every channel in one place'). The buyer quotes here are about the integration layer behind the screen failing, not the screen itself, so the KDS only kills this pain if the channel connections hold. That is the proof the angle needs.",
      "cites": ["src:17", "src:33", "src:38"]
    },
    {
      "id": "pain:locked-in-and-cant-leave",
      "statement": "You find out what leaving costs only when you try to leave, and by then it's tens of thousands.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "Contracts auto-renew, terms get changed mid-term, and a cancellation fee appears that the operator never knew they had agreed to.",
        "operational": "Owners open cancellation cases that get escalated and never close, keep paying while the account stays open, and stay on a system they have stopped trusting because leaving costs more than staying.",
        "personal": "Weeks of the owner's own time go into a cancellation that keeps being escalated while billing continues (src:37)."
      },
      "workflow": "The renewal date buried in the agreement (src:9 describes it embedded in a URL link rather than supplied) and the cancellation case in the vendor's support portal: the owner asks to close the account, the case is escalated, and the card keeps getting charged.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The auto-renewal date passing, which locks in another term with charges the operator did not expect.",
          "cites": ["src:7"]
        },
        {
          "event": "Deciding to switch POS, which is when the exit fee is discovered.",
          "cites": ["src:3", "src:9"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "$30,000 to leave",
              "cites": ["src:3"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "we have been trying to cancel for weeks now but have been given the run around",
              "cites": ["src:37"]
            },
            {
              "situation": "venting",
              "verbatim": "They changed the terms and conditions in the middle of our contract",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "15k cancellation fee for the 3 year contract you were never advised you had.",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "An exit price in the tens of thousands (src:3 at $30,000, src:9 at $15,000) on top of months of paying for a system they have already stopped using.",
          "fears": "Signing again and being trapped again; src:37 opens with a warning to anyone considering signing up.",
          "dream_outcome": "Plain terms, a known exit price, and the ability to leave without a fight."
        }
      },
      "segments": ["seg:independent", "seg:multi"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company touches this; it is a commercial-terms pain. Toast's own buyers raise the mirror-image version of it in the sources read (src:43 on cost and no help, src:47 on a guest-facing fee added to their online orders without their say), so this is a pain to be honest about in positioning and objection handling rather than one to market against competitors on.",
      "cites": ["src:3", "src:37", "src:9"]
    },
    {
      "id": "pain:inventory-in-the-dark",
      "statement": "The inventory module is useless, so food cost lives in a spreadsheet somebody counts by hand.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "Stock counts in the POS do not match what is on the shelf, and food cost is not visible in the system.",
        "operational": "Counts get done on paper or in a spreadsheet and typed in later, or the operator buys a separate inventory tool and gives up on the POS module.",
        "personal": null,
        "personal_note": "Both sources are short asides inside longer reviews about other things; neither describes the count itself or who does it. See q:pains-inventory."
      },
      "workflow": "The weekly count in the walk-in and dry store, written down and typed into a spreadsheet because the POS's inventory module cannot be trusted, then reconciled by hand against the POS's sales reports.",
      "type": "felt",
      "confidence": "low",
      "triggers": [],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "The inventory module is laughably bad",
              "cites": ["src:12"]
            },
            {
              "situation": "venting",
              "verbatim": "Poor inventory management",
              "cites": ["src:10"]
            }
          ],
          "costs_them": "Food cost that is only knowable by hand, against a median full-service pre-tax margin of 2.8% (src:46) where a point of food cost is most of the profit.",
          "fears": "No source shows the fear; both quotes stop at the module being bad.",
          "dream_outcome": "Stock that is accurate in the system without a manual count, so food cost is visible before the month closes."
        }
      },
      "segments": ["seg:independent"],
      "feature_ref": "feat:inventory",
      "feature_note": "feat:inventory is the direct answer, but the evidence for the pain is thin: two short asides from buyers of two competitors, five and six years apart. Treat this as the weakest row in the map until q:pains-inventory is answered.",
      "cites": ["src:12", "src:10"]
    },
    {
      "id": "pain:reports-that-dont-answer-the-question",
      "statement": "You go to ten different screens for a report and still end up rebuilding it in Excel.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "The numbers are spread across separate screens, do not export in a usable shape, and do not reconcile with what was actually taken.",
        "operational": "Owners pull reports one at a time and rebuild them in a spreadsheet, or spend the time on the phone with support trying to make sense of them.",
        "personal": null,
        "personal_note": "The closest any source comes is src:14 on spending hours trying to make sense of reports, which is time rather than a personal cost. See q:pains-personal-rung."
      },
      "workflow": "The back office after close, pulling last week's sales, tax and payment reports one screen at a time out of the POS back end and rebuilding them in a spreadsheet because the export will not pivot.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "The back of house reporting is a disaster",
              "cites": ["src:14"]
            },
            {
              "situation": "venting",
              "verbatim": "Need to go to 10 different window for report",
              "cites": ["src:29"]
            }
          ],
          "costs_them": "Hours after close rebuilding numbers the system already has; src:14 describes spending hours trying to make sense of them.",
          "fears": "Making a pricing or staffing decision on a number that turns out to be wrong; src:29 says sales tax is not properly counted.",
          "dream_outcome": "One screen that answers the question they actually have, and an export that can be worked on."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "back end reports are not helpful",
              "cites": ["src:15"]
            }
          ],
          "costs_them": "Time spent assembling the weekly numbers for the owner by hand.",
          "fears": "No source shows the fear; the quote stops at the reports not being helpful.",
          "dream_outcome": "Numbers they can hand to the owner straight out of the system."
        }
      },
      "segments": ["seg:independent"],
      "feature_ref": null,
      "feature_note": "brain/company lists no reporting or analytics feature. feat:iq is the nearest thing, but it forecasts forward and these buyers are asking for last week's numbers to reconcile. Either there is a reporting surface the company artifact did not capture, or this is a real gap the offer step needs to know about.",
      "cites": ["src:14", "src:29"]
    },
    {
      "id": "pain:schedule-by-guesswork",
      "statement": "The schedule gets built in Excel from last year's numbers, and you find out what it cost after payroll runs.",
      "element": "b2b:ease_of_doing_business:organization",
      "shape": {
        "surface": "The schedule lives in a spreadsheet and gets communicated by text, and the dollar cost of the written schedule is not visible before the week starts.",
        "operational": "The GM rebuilds the schedule in Excel each week, chases swaps and availability across texts, messenger, group chats and email, and scrolls back to last year's sales in the POS reports to guess how many people to roster.",
        "personal": null,
        "personal_note": "The 7shifts reviewers describe the old process with relief rather than describing what it cost them, which is characteristic of a latent pain: nobody was writing down the personal cost of the thing they had accepted as normal. See q:pains-iq-reaction."
      },
      "workflow": "The weekly schedule build in Excel on the back-office computer, pushed out over texts, messenger and group chats, with last year's sales pulled from the POS reports in another window to guess the cover count for each day.",
      "type": "latent",
      "confidence": "medium",
      "revealed_by": "feat:iq",
      "triggers": [],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "you still need third-party add-on apps to make it a complete POS package (things as basic as employee scheduling)",
              "cites": ["src:16"]
            },
            {
              "situation": "when_looking",
              "verbatim": "I want to know total dollar spend for the written schedule per day",
              "cites": ["src:22"]
            },
            {
              "situation": "when_looking",
              "verbatim": "I can quickly scroll back to last year and see our sales trends",
              "cites": ["src:23"]
            }
          ],
          "costs_them": "Labor committed before its cost is known, against a median full-service pre-tax margin of 2.8% (src:46), plus another subscription to fill a gap the POS left (src:16).",
          "fears": "No source shows the fear directly; the closest is src:22 wanting the daily dollar spend before the week is worked, which implies being surprised by it after.",
          "dream_outcome": "Seeing what the schedule costs and what the week is forecast to do before publishing it, in the same system that takes the money."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I was an excel user for my scheduling",
              "cites": ["src:20"]
            },
            {
              "situation": "venting",
              "verbatim": "eliminating the old multi tiered way of doing it with texts, messengers, google chats, emails, and in person requests",
              "cites": ["src:21"]
            }
          ],
          "costs_them": "A weekly rebuild in a spreadsheet plus the swap chase across four or five channels (src:21).",
          "fears": "No source shows the fear; both quotes describe the old workaround rather than a worry about it.",
          "dream_outcome": "One place where the schedule is built, published and swapped, with the labor number attached."
        }
      },
      "segments": ["seg:independent", "seg:multi"],
      "feature_ref": "feat:labor",
